    #[test]
    fn test_restore_code_actions_on_format() {
        assert_migrate_with_migrations(
            &[MigrationType::Json(
                migrations::m_2025_10_16::restore_code_actions_on_format,
            )],
            &r#"{
                "formatter": {
                    "code_action": "foo"
                }
            }"#
            .unindent(),
            Some(
                &r#"{
                    "code_actions_on_format": {
                        "foo": true
                    },
                    "formatter": []
                }"#
                .unindent(),
            ),
        );

        assert_migrate_with_migrations(
            &[MigrationType::Json(
                migrations::m_2025_10_16::restore_code_actions_on_format,
            )],
            &r#"{
                "formatter": [
                    { "code_action": "foo" },
                    "auto"
                ]
            }"#
            .unindent(),
            None,
        );

        assert_migrate_with_migrations(
            &[MigrationType::Json(
                migrations::m_2025_10_16::restore_code_actions_on_format,
            )],
            &r#"{
                "formatter": {
                    "code_action": "foo"
