    #[test]
    fn test_make_auto_indent_an_enum() {
        // Empty settings should not change
        assert_migrate_with_migrations(
            &[MigrationType::Json(
                migrations::m_2025_01_27::make_auto_indent_an_enum,
            )],
            &r#"{ }"#.unindent(),
            None,
        );

        // true should become "syntax_aware"
        assert_migrate_with_migrations(
            &[MigrationType::Json(
                migrations::m_2025_01_27::make_auto_indent_an_enum,
            )],
            &r#"{
                "auto_indent": true
            }"#
            .unindent(),
            Some(
                &r#"{
                "auto_indent": "syntax_aware"
            }"#
                .unindent(),
            ),
        );

        // false should become "none"
        assert_migrate_with_migrations(
            &[MigrationType::Json(
                migrations::m_2025_01_27::make_auto_indent_an_enum,
            )],
            &r#"{
                "auto_indent": false
            }"#
            .unindent(),
            Some(
                &r#"{
                "auto_indent": "none"
            }"#
                .unindent(),
            ),
        );

        // Already valid enum values should not change
        assert_migrate_with_migrations(
            &[MigrationType::Json(
                migrations::m_2025_01_27::make_auto_indent_an_enum,
            )],
            &r#"{
                "auto_indent": "preserve_indent"
            }"#
            .unindent(),
            None,
        );

        // Should also work inside languages
        assert_migrate_with_migrations(
            &[MigrationType::Json(
                migrations::m_2025_01_27::make_auto_indent_an_enum,
            )],
            &r#"{
                "auto_indent": true,
                "languages": {
                    "Python": {
                        "auto_indent": false
                    }
                }
            }"#
            .unindent(),
            Some(
                &r#"{
                    "auto_indent": "syntax_aware",
                    "languages": {
                        "Python": {
                            "auto_indent": "none"
                        }
                    }
                }"#
                .unindent(),
            ),
        );
    }

